import { FC, useMemo, useRef } from 'react';

import { Cover } from 'components';
import { useDataRefreshForTab } from 'contexts/DataRefreshModal/useDataRefreshForTab';
import { FilterRegistry } from 'domain/Filter';
import { usePageFilterApplied, usePageIndexes } from 'hooks';
import { KPI_CONFIGS } from 'pages/pillars/ValueCreation/VolumePages/config';
import { useVolumePagesKpi } from 'pages/pillars/ValueCreation/VolumePages/contexts';
import { useKpiEndpoint } from 'pages/pillars/ValueCreation/VolumePages/hooks/useKpiEndpoint';
import { useGlobalPeriod } from 'pages/pillars/ValueCreation/VolumePages/tabs/Global/hooks';
import {
  ExportSummaryPageHeader,
  SummaryResultsSection,
} from 'pages/pillars/ValueCreation/VolumePages/tabs/Summary/components';
import { pageSections } from 'pages/pillars/ValueCreation/VolumePages/tabs/Summary/constants/sections';
import { getVolumePagesPageName } from 'pages/pillars/ValueCreation/VolumePages/utils';
import {
  StyledExportPageContent,
  StyledExportPageSection,
} from 'shared/Styles/exportPages.styles';

interface SummaryProps {
  dataTestId?: string;
}

export const Summary: FC<SummaryProps> = ({ dataTestId }) => {
  useDataRefreshForTab('volume-page-global');
  const { kpi } = useVolumePagesKpi();
  const { applied } = usePageFilterApplied(getVolumePagesPageName(kpi));
  const { endpoints: kpiEndpoints, reporttype } = useKpiEndpoint(
    KPI_CONFIGS[kpi],
    applied,
  );

  const containerRef = useRef<HTMLDivElement>(null);
  const { getPageByName } = usePageIndexes(containerRef);

  const { monthYear, period } = useGlobalPeriod(kpi);

  const globalCoverLink = useMemo(
    () =>
      `/value-creation?${FilterRegistry.buildFilterQueryString({
        zone: 'ABI',
        country: 'ABI',
      })}`,
    [],
  );

  return (
    <div
      ref={containerRef}
      data-testid={dataTestId ? `tabpanel-summary-${dataTestId}` : undefined}
    >
      <StyledExportPageContent
        data-testid={
          dataTestId
            ? `tabpanel-summary-export-page-content-${dataTestId}`
            : undefined
        }
      >
        <ExportSummaryPageHeader
          monthYear={monthYear}
          dataTestId={dataTestId}
        />
        <SummaryResultsSection
          globalCoverLink={globalCoverLink}
          getPageByName={getPageByName}
          dataTestId={dataTestId}
          monthYear={monthYear}
          period={period}
          kpiEndpoints={kpiEndpoints}
          reporttype={reporttype}
        />

        <StyledExportPageSection data-page-name={pageSections.backCover}>
          <Cover
            dataTestId={
              dataTestId ? `${dataTestId}-summary-thank-you` : undefined
            }
            link={globalCoverLink}
            name="Thank You"
            centerLogo
            showLogo
          />
        </StyledExportPageSection>
      </StyledExportPageContent>
    </div>
  );
};
